module.exports = net

function net (id) {
  const label = `[${id}@${__filename}]`
  const _ = {}
  const sub = {}
  const hub = {}
  const io = { invite, accept, connect, on: {} }
  return { io, _ }

  // connect: registers a tunnel adapter (e.g. ws_client) as a named peer.
  // Populates _[name] so components can call e.g. _.backend(type, refs, data).
  // Also binds the tunnel's incoming rx so messages flow back through io.on[name].
  function connect (name, tunnel) {
    if (!io.on[name]) throw new Error(`${label} no protocol handler for "${name}" — set io.on.${name} before calling io.connect()`)
    const rx = function (M) {
      if (io.on[name]) io.on[name](M)
    }
    add(name, tunnel.tx.bind(tunnel), tunnel.id, rx, hub)
    tunnel.bind(rx)
  }

  function forward (to, M) {
    for (const key of Object.keys(sub)) {
      if (to.startsWith(key)) return sub[key].tx(M)
    }
    for (const key of Object.keys(hub)) {
      if (to.startsWith(key)) return hub[key].tx(M)
    }
    console.error(`${label} - cant forward to unknown recipient "${to}"`)
  }

  function invite (name, ids) {
    if (!io.on[name]) throw new Error(`${label} no protocol handler for "${name}"`)
    const inv = Object.assign(invite_fn, { ids })
    return inv

    function invite_fn (tx) {
      const rx = router(sub)
      add(name, tx, tx.id, rx, sub)
      return rx
    }
  }

  function accept (invite) {
    const rx = router(hub)
    const tx = invite(Object.assign(rx, { id }))
    for (const [name, to] of Object.entries(invite.ids)) {
      if (hub[to]) throw new Error(`${label} already connected to "${to}"`)
      if (!io.on[name]) throw new Error(`${label} no "${name}" protocol for "${to}"`)
      add(name, tx, to, rx, hub)
    }
  }

  function router ($) {
    return function rx (M) {
      const { head: [by, to, mid] } = M
      console.log(`${label}\n  [by] ${by}\n  [to] ${to}\n  [mid] ${mid}`)
      if (to !== id) return forward(to, M)
      if (!$[by]) throw new Error(`${label} unknown sender "${by}"`)
      const { name } = $[by].state
      if (!io.on[name]) throw new Error(`${label} no "${name}" protocol for "${to}"`)
      io.on[name](M)
    }
  }

  function add (name, tx, to, rx, $) {
    const { state } = $[to] = { rx, tx, state: { name, to, mid: 0 } }
    _[name] = send
    function send (type, refs, data) {
      const head = [id, to, state.mid++]
      const meta = { time: Date.now(), stack: (new Error().stack) }
      const msg = { head, refs: refs || {}, type, meta }
      if (arguments.length >= 3) msg.data = data
      tx(msg)
      return head
    }
  }
}
